	,rnd: function(min,max,sign) {
		var sign1 = sign;
		if(sign1 == null) {
			sign1 = false;
		}
		if(sign1) {
			return (min + Math.random() * (max - min)) * (Std.random(2) * 2 - 1);
		} else {
			return min + Math.random() * (max - min);
		}
	}
